class Solution:
    def minDifference(self, n, k):
        best = [None]
        bd = float('inf')
        def dfs(rem, cnt, lo, cur):
            nonlocal bd
            if cnt == k - 1:
                if rem >= lo:
                    lst = cur + [rem]
                    d = max(lst) - min(lst)
                    if d < bd:
                        bd = d
                        best[0] = lst
                return
            i = lo
            while i * i <= rem:
                if rem % i == 0:
                    dfs(rem // i, cnt + 1, i, cur + [i])
                i += 1
        dfs(n, 0, 1, [])
        return best[0]

