class Solution {
    int bd = INT_MAX;
    vector<int> best;
    void dfs(int rem, int cnt, int lo, int k, vector<int>& cur) {
        if (cnt == k - 1) {
            if (rem >= lo) {
                vector<int> lst = cur;
                lst.push_back(rem);
                int d = *max_element(lst.begin(), lst.end()) - *min_element(lst.begin(), lst.end());
                if (d < bd) { bd = d; best = lst; }
            }
            return;
        }
        for (int i = lo; (long long)i * i <= rem; i++)
            if (rem % i == 0) {
                cur.push_back(i);
                dfs(rem / i, cnt + 1, i, k, cur);
                cur.pop_back();
            }
    }
public:
    vector<int> minDifference(int n, int k) {
        vector<int> cur;
        dfs(n, 0, 1, k, cur);
        return best;
    }
};

