class Solution {
    private int bd = Integer.MAX_VALUE;
    private List<Integer> best;
    private void dfs(int rem, int cnt, int lo, int k, List<Integer> cur) {
        if (cnt == k - 1) {
            if (rem >= lo) {
                List<Integer> lst = new ArrayList<>(cur);
                lst.add(rem);
                int mx = Collections.max(lst), mn = Collections.min(lst);
                if (mx - mn < bd) { bd = mx - mn; best = lst; }
            }
            return;
        }
        for (int i = lo; (long) i * i <= rem; i++)
            if (rem % i == 0) {
                cur.add(i);
                dfs(rem / i, cnt + 1, i, k, cur);
                cur.remove(cur.size() - 1);
            }
    }
    public List<Integer> minDifference(int n, int k) {
        dfs(n, 0, 1, k, new ArrayList<>());
        return best;
    }
}

