var minDifference = function(n, k) {
    let bd = Infinity, best = null;
    const dfs = (rem, cnt, lo, cur) => {
        if (cnt === k - 1) {
            if (rem >= lo) {
                const lst = cur.concat([rem]);
                const d = Math.max(...lst) - Math.min(...lst);
                if (d < bd) { bd = d; best = lst; }
            }
            return;
        }
        for (let i = lo; i * i <= rem; i++)
            if (rem % i === 0) dfs(Math.floor(rem / i), cnt + 1, i, cur.concat([i]));
    };
    dfs(n, 0, 1, []);
    return best;
};
